import { z } from 'zod';

/** IDs are kebab-case so content files stay predictable and URL-safe. */
export const Id = z
  .string()
  .regex(/^[a-z0-9]+(-[a-z0-9]+)*$/, 'IDs must be kebab-case, e.g. "ask-about-guitar"');

/** Jimi's emotional state while giving a response. Drives the UI later. */
export const MoodSchema = z.enum(['warm', 'nervous', 'guarded', 'playful', 'reflective']);

/** A single reply Jimi can give. */
export const ResponseSchema = z.object({
  mood: MoodSchema.default('warm'),
  lines: z.array(z.string().min(1)).min(1),
});

